WHERE LIB_ID = #{libraryId}


        AND (ORG_MSTR_CODE, ORG_CODE) IN

            (#{district.regionCode}, #{district.districtCode})


    AND 1 = 0

AND ACTIVITY_DATE >= #{filter.from}
AND ACTIVITY_DATE <= #{filter.to}
AND REPORT_ROLE = #{filter.role}

WHERE LIB_ID = #{libraryId} AND ORG_MSTR_CODE = #{key.district.regionCode}
    AND ORG_CODE = #{key.district.districtCode} AND ACTIVITY_DATE = #{key.date}
    AND SLOT_CODE = #{key.slot}
